const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18m-13 5h2m4 0h2"/>',
 exam:'<path d="M9 4H5v17h14V4h-4M9 3h6v4H9zm-1 9h8m-8 4h5"/>',
 bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-11 12a2 2 0 0 0 4 0"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
 pin:'<path d="M12 22v-7M8 3h8l-1 6 4 4v2H5v-2l4-4z"/>',
 location:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 unknown:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-1 1-2 1-2 3m0 3h.01"/>',
 optional:'<circle cx="12" cy="12" r="9"/><path d="M8 12h8"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 edit:'<path d="m15 4 5 5M3 21l5-1L21 7l-5-5L3 15z"/>',
 settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',
 people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 6"/>',
 logout:'<path d="M9 3H3v18h6m5-14 5 5-5 5m-7-5h12"/>',
 book:'<path d="M12 5C7 2 3 4 3 4v16s4-2 9 1c5-3 9-1 9-1V4s-4-2-9 1zm0 0v16"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',
 link:'<path d="m10 13 4-4m-7 6-2 2a4 4 0 0 0 6 6l4-4a4 4 0 0 0-1-6m3-2 2-2a4 4 0 0 0-6-6L9 7a4 4 0 0 0 1 6"/>',
 shield:'<path d="M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7z"/><path d="m8 12 3 3 5-6"/>',
 leaf:'<path d="M20 3C7 2 2 7 5 14c3 8 14 6 15-11ZM4 21 15 9"/>',
 refresh:'<path d="M20 7v5h-5M4 17v-5h5m-4-5a8 8 0 0 1 14-2l1 2M4 17l1 2a8 8 0 0 0 14-2"/>'
};
const icon = (name,cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const state = { user:null, classes:[], classId:localStorage.getItem('medclass-class'), data:null, page:'home', view:'agenda', search:'', filters:{subject:'',type:'',subgroup:'',attendance:''}, month:null, stream:null, connected:true, loading:false };
let csrf='', toastTimer, lastVisit=null, authMode='login', invitationCode=new URLSearchParams(location.hash.slice(1)).get('join')||'';
const attendance = {required:{label:'Required',icon:'check'},not_required:{label:'Not required',icon:'optional'},unknown:{label:'Unknown',icon:'unknown'}};
const typeNames={lecture:'Lecture',practical:'Practical',tutorial:'Tutorial',exam:'Exam',other:'Other'};
const api = async(path,options={}) => {
  const response=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...options.headers}});
  const result=await response.json(); if (!response.ok) {const error=new Error(result.error||'Unable to complete this request.'); error.status=response.status; throw error; } return result;
};
const send=(path,body={},method='POST')=>api(path,{method,body:JSON.stringify(body)});
const base=()=>`/classes/${state.classId}`;
const editor=()=>state.data && ['admin','editor'].includes(state.data.role);
const admin=()=>state.data?.role==='admin';
const toast=message=>{ $('#toast').textContent=message; $('#toast').classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500); };
const zone=()=>state.data?.class.timezone||'Europe/Paris';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:zone(),year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const localTime=()=>new Intl.DateTimeFormat('en-GB',{timeZone:zone(),hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());
const dateFormat=(date,options={month:'short',day:'numeric'})=>date?new Intl.DateTimeFormat('en-GB',{...options,timeZone:'UTC'}).format(new Date(date+'T12:00:00Z')):'To be confirmed';
const stamp=iso=>new Intl.DateTimeFormat('en-GB',{timeZone:zone(),month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(iso));
const relative=iso=>{const min=Math.floor((Date.now()-new Date(iso))/60000);return min<1?'Just now':min<60?`${min} min ago`:min<1440?`${Math.floor(min/60)}h ago`:stamp(iso);};
const upcoming=e=>e.status!=='cancelled'&&e.date&&(e.date>today()||(e.date===today()&&(!e.end||e.end>=localTime())));
const sorted=events=>[...events].sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||(a.start||'99').localeCompare(b.start||'99'));
const eventById=id=>state.data.events.find(e=>e.id===id);
const badge=e=>{const a=attendance[e.attendance]||attendance.unknown;return `<span class="attendance ${esc(e.attendance)}">${icon(a.icon)}${a.label}</span>`;};
const empty=(title,message,ic='calendar')=>`<div class="empty-state">${icon(ic)}<h3>${esc(title)}</h3><p>${esc(message)}</p></div>`;

async function boot() {
  try {
    const me=await api('/me'); state.user=me.user; state.classes=me.classes; csrf=me.csrf;
    if(!state.classes.some(c=>c.id===state.classId))state.classId=state.classes[0]?.id;
    if(invitationCode){ await send('/join',{code:invitationCode}); invitationCode='';history.replaceState(null,'',location.pathname); return boot(); }
    if(!state.classId){renderNoClass();return;}
    await loadClass(true); connect();
  } catch(error) {if(error.status===401){renderAuth();}else renderFatal(error);}
}
async function loadClass(first=false) {
  const requested=state.classId;
  const data=await api(`/classes/${requested}`);
  if(requested!==state.classId)return;
  if(first) lastVisit=data.lastVisit;
  state.data=data; if(first)state.month=today().slice(0,7); state.connected=navigator.onLine;render();
  if(first) {window.scrollTo({top:0});$('#main')?.focus({preventScroll:true});await send(`${base()}/visit`);}
}
function connect() {
  state.stream?.close(); state.stream=new EventSource(`/api${base()}/stream`);
  state.stream.addEventListener('ready',()=>{state.connected=true;connectionLabel();loadClass().catch(handleLoadError);});
  state.stream.addEventListener('change',()=>loadClass().catch(handleLoadError));
  state.stream.onerror=()=>{state.connected=false;connectionLabel();};
}
function connectionLabel(){const el=$('#connection');if(el){el.className=`connection ${state.connected?'':'offline'}`;el.innerHTML=`<span class="live-dot"></span>${state.connected?'Live updates on':'Connection lost · information may be outdated'}`;} }
function handleLoadError(error){if(error.status===401){state.stream?.close();state.user=null;renderAuth();}else if(error.status===403){state.stream?.close();boot();}else{state.connected=false;connectionLabel();toast(error.message);}}
window.addEventListener('offline',()=>{state.connected=false;connectionLabel();});
window.addEventListener('online',()=>{loadClass().catch(handleLoadError);connect();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.user&&state.classId)loadClass().catch(handleLoadError);});
setInterval(()=>{if(state.user&&state.data&&!document.hidden)loadClass().catch(handleLoadError);},60000);

function renderAuth(error='') {
  const register=authMode==='register';
  $('#app').innerHTML=`<div class="auth-layout"><section class="auth-story"><a class="brand" href="/"> <img src="/icon.svg" width="38" height="38" alt="">MedClass<span class="brand-dot">.</span></a><div class="auth-copy"><span class="eyebrow">LESS SEARCHING. MORE LEARNING.</span><h1>Your class.<br>Your schedule.<br><em>All together.</em></h1><p>A little clarity for busy medical students.<br>Know where to be, what to bring, and what’s changed.</p><div class="auth-sample"><span class="sample-icon">${icon('calendar')}</span><div><strong>One place. Everyone in the know.</strong><span>Schedules, exams & the updates that matter.</span></div>${icon('check')}</div></div><div class="auth-footer">Made for the way your class works. ${icon('leaf')}</div></section><main id="main" class="auth-panel"><div class="auth-card"><span class="eyebrow">YOUR CLASS SPACE</span><h2>${register?'Join your class':'Welcome back'}</h2><p class="muted">${register?'Use your invitation to create a student account.':'Sign in to see what’s happening in your class.'}</p><form id="auth-form">${register?'<label>Your name<input name="name" autocomplete="name" required maxlength="100" placeholder="Alex Morgan"></label>':''}<label>Email address<input type="email" name="email" autocomplete="email" required placeholder="you@university.edu"></label><label>Password<input type="password" name="password" autocomplete="${register?'new-password':'current-password'}" minlength="12" maxlength="128" required placeholder="${register?'At least 12 characters':'Your password'}"></label>${register?`<label>Invitation code<input name="code" required value="${esc(invitationCode)}" placeholder="Paste the code from your class admin"></label>`:''}<p class="form-error" role="alert">${esc(error)}</p><button class="button primary full" type="submit">${register?'Create account & join':'Sign in'}${icon('arrow')}</button></form><p class="auth-switch">${register?'Already a member?':'Have a class invitation?'} <button class="text-button" data-action="auth-switch">${register?'Sign in':'Join your class'}</button></p><div class="demo-access"><span class="demo-label">EXPLORE THE DEMONSTRATION</span><p>A sample medical class, with clearly labeled demo data.</p><div class="demo-buttons"><button class="button secondary" data-action="demo-login" data-role="student">${icon('book')}Student</button><button class="button secondary" data-action="demo-login" data-role="admin">${icon('settings')}Admin</button><button class="button secondary" data-action="demo-login" data-role="editor">Editor</button></div></div><p class="privacy-line">${icon('shield')} A private space for your class members.</p></div></main></div>`;
  $('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;const body=Object.fromEntries(new FormData(e.target));try{const result=await send(`/auth/${authMode}`,body);csrf=result.csrf;invitationCode='';history.replaceState(null,'',location.pathname);await boot();}catch(error){$('.form-error').textContent=error.message;button.disabled=false;}};
}
function renderFatal(error){$('#app').innerHTML=`<main id="main" class="fatal">${empty('We couldn’t open your class',error.message,'unknown')}<button class="button primary" data-action="reload">Try again</button></main>`;}
function renderNoClass(){ $('#app').innerHTML=`<main id="main" class="fatal"><img src="/icon.svg" width="48" height="48" alt="MedClass"><h1>Let’s find your class</h1><p>Enter an invitation code from your class administrator.</p><form id="join-form"><label>Invitation code<input name="code" required></label><button class="button primary">Join class</button><p class="form-error" role="alert"></p></form><button class="text-button" data-action="logout">Sign out</button></main>`;$('#join-form').onsubmit=async e=>{e.preventDefault();try{await send('/join',Object.fromEntries(new FormData(e.target)));await boot();}catch(error){$('.form-error').textContent=error.message;}}; }

function render() {
  const unread=state.data.notifications.filter(n=>!n.is_read).length;
  const nav=[['home','home','Home'],['schedule','calendar','Schedule'],['exams','exam','Exams'],['updates','bell','Updates']];
  $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="/" data-action="home"><img src="/icon.svg" width="36" height="36" alt="">MedClass<span class="brand-dot">.</span></a><div class="class-picker"><span class="eyebrow">YOUR CLASS</span><label class="sr-only" for="class-select">Choose class</label><select id="class-select">${state.classes.map(c=>`<option value="${esc(c.id)}" ${c.id===state.classId?'selected':''}>${esc(c.name)}</option>`).join('')}</select><span class="class-sub">${esc(state.data.subgroup||'All groups')} · ${esc(state.data.role==='student'?'Student':state.data.role==='admin'?'Administrator':'Class representative')}</span></div><nav class="main-nav" aria-label="Main navigation">${nav.map(([page,ic,label])=>`<button data-page="${page}" class="nav-link ${state.page===page?'active':''}" ${state.page===page?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${page==='updates'&&unread?`<span class="nav-count">${unread}</span>`:''}</button>`).join('')}${admin()?`<div class="nav-divider"></div><span class="eyebrow nav-heading">CLASS MANAGEMENT</span><button data-page="admin" class="nav-link ${state.page==='admin'?'active':''}">${icon('people')}<span>Manage class</span></button>`:''}</nav><div class="sidebar-bottom"><div class="quiet-note">${icon('leaf')}<p>A little clarity.<br>A better class day.</p></div><button class="nav-link join-link" data-action="join">${icon('plus')}Join another class</button><div class="profile"><span class="avatar">${esc(state.user.name.split(' ').map(n=>n[0]).join('').slice(0,2))}</span><div><strong>${esc(state.user.name)}</strong><span>${esc(state.data.role)}</span></div><button class="icon-button" data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb">Your class space <span>/</span> ${esc(state.page==='admin'?'Manage class':state.page[0].toUpperCase()+state.page.slice(1))}</span><div class="topbar-actions"><span id="connection" class="connection"></span><button class="icon-button notification-button" data-page="updates" aria-label="Updates${unread?`, ${unread} unread`:''}">${icon('bell')}${unread?'<span class="notification-dot"></span>':''}</button><button class="avatar small account-button" data-action="account" aria-label="Account and class settings">${esc(state.user.name[0])}</button></div></header><main id="main" tabindex="-1">${state.data.class.demo?'<div class="demo-banner"><span>DEMO CLASS</span> Sample schedules and announcements. For demonstration only.</div>':''}${state.page==='home'?homePage():state.page==='schedule'?schedulePage():state.page==='exams'?examsPage():state.page==='updates'?updatesPage():adminPage()}</main><footer class="page-footer"><span>MedClass <span class="muted">· Your class, in the know.</span></span><span>All times in ${esc(zone())}</span></footer></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav.map(([page,ic,label])=>`<button data-page="${page}" class="${state.page===page?'active':''}" ${state.page===page?'aria-current="page"':''}>${icon(ic)}<span>${label}${page==='updates'&&unread?` (${unread})`:''}</span></button>`).join('')}${admin()?`<button data-page="admin" class="${state.page==='admin'?'active':''}">${icon('settings')}<span>Admin</span></button>`:''}</nav></div>`;
  connectionLabel();
  $('#class-select').onchange=async e=>{state.classId=e.target.value;localStorage.setItem('medclass-class',state.classId);state.page='home';state.filters={subject:'',type:'',subgroup:'',attendance:''};state.search='';try{await loadClass(true);connect();}catch(error){handleLoadError(error);}};
  bindFilters(); if(state.page==='admin')loadAdmin();
}

function pageHeading(kicker,title,description,buttons=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${buttons}</div></div>`;}
function homePage(){
  const events=state.data.events, day=today(), todays=sorted(events.filter(e=>e.date===day)), exams=sorted(events.filter(e=>e.type==='exam'&&upcoming(e))), next=sorted(events.filter(upcoming))[0];
  const urgent=state.data.announcements.filter(a=>a.priority==='urgent'||a.pinned),recent=state.data.notifications.filter(n=>n.kind==='change').slice(0,3);
  const changed=lastVisit?state.data.notifications.filter(n=>n.created_at>lastVisit).length:0;
  const greeting=Number(localTime().slice(0,2))<12?'Good morning':Number(localTime().slice(0,2))<18?'Good afternoon':'Good evening';
  return `${pageHeading(dateFormat(day,{weekday:'long',day:'numeric',month:'long',year:'numeric'}).toUpperCase(),`${greeting}, ${esc(state.user.name.split(' ')[0])}<span class="greeting-dot">.</span>`,'A clear picture of your day. You’re in the right place.',editor()?`<button class="button primary" data-action="new-event">${icon('plus')}Create event</button>`:'')}${changed?`<button class="since-visit" data-page="updates">${icon('refresh')}<strong>${changed} update${changed===1?'':'s'} since your last visit</strong><span>See what’s changed ${icon('arrow')}</span></button>`:''}<div class="dashboard-grid"><div class="dashboard-main">${urgent.map(announcementCard).join('')}<section class="today-section"><div class="section-heading"><h2>Today’s schedule <span class="count-pill">${todays.length}</span></h2><button class="text-button" data-page="schedule">Full schedule ${icon('arrow')}</button></div><p class="section-subtitle">${todays.filter(e=>e.status!=='cancelled').length?`${todays.filter(e=>e.status!=='cancelled').length} session${todays.filter(e=>e.status!=='cancelled').length===1?'':'s'} on your calendar. Here’s what you need to know.`:'A little room to breathe. Your day is clear.'}</p><div class="event-list">${todays.length?todays.map(e=>eventCard(e)).join(''):empty('No classes today','Check your next event or take a well-earned break.')}</div></section><section><div class="section-heading"><h2>Recently changed</h2><button class="text-button" data-page="updates">All updates ${icon('arrow')}</button></div><div class="recent-list">${recent.length?recent.map(n=>`<button class="recent-item" ${n.event_id?`data-action="detail" data-id="${esc(n.event_id)}"`:'data-page="updates"'}><span class="change-icon">${icon('refresh')}</span><div><strong>${esc(n.title)}</strong><p>${esc(n.message)}</p><span>${esc(n.author)} · ${relative(n.created_at)}</span></div>${icon('chevron')}</button>`).join(''):empty('You’re all caught up','Schedule changes will appear here.','check')}</div></section></div><aside class="dashboard-aside"><section class="next-card"><span class="eyebrow">${icon('clock')}UP NEXT</span>${next?`<h2>${esc(next.title)}</h2><span class="next-subject">${esc(next.subject)} · ${typeNames[next.type]}</span><div class="next-details"><p>${icon('calendar')}${next.date===day?'Today':dateFormat(next.date,{weekday:'short',day:'numeric',month:'short'})}</p><p>${icon('clock')}${esc(next.start||'Time to be confirmed')}${next.end?' – '+esc(next.end):''}</p><p>${icon('location')}${esc([next.building,next.room].filter(Boolean).join(' · ')||'Location to be confirmed')}</p></div>${badge(next)}<button class="next-link" data-action="detail" data-id="${next.id}">View event details ${icon('arrow')}</button>`:'<h2>All clear for now</h2><p>Upcoming events will appear here once confirmed.</p>'}</section><section class="exam-preview"><div class="section-heading"><h2>On the horizon</h2>${icon('exam')}</div><p class="section-subtitle">A little preparation goes a long way.</p>${exams.slice(0,3).map(e=>`<button class="exam-mini" data-action="detail" data-id="${e.id}"><span class="date-tile"><strong>${dateFormat(e.date,{day:'numeric'})}</strong><span>${dateFormat(e.date,{month:'short'})}</span></span><span><strong>${esc(e.subject)}</strong><span>${esc(e.start||'Time to be confirmed')}${e.status==='rescheduled'?' · Rescheduled':''}</span></span></button>`).join('')||'<p class="muted">No upcoming exams.</p>'}<button class="text-button" data-page="exams">View all exams ${icon('arrow')}</button></section><section class="small-note">${icon('shield')}<div><strong>Details still to be confirmed?</strong><p>“Unknown” means we’re waiting for confirmation. Keep an eye on your updates.</p></div></section></aside></div>${state.data.announcements.some(a=>!urgent.includes(a))?`<section class="announcements-section"><div class="section-heading"><h2>Class noticeboard</h2>${editor()?'<button class="text-button" data-action="new-announcement">Post announcement</button>':''}</div><div class="notice-grid">${state.data.announcements.filter(a=>!urgent.includes(a)).map(announcementCard).join('')}</div></section>`:''}`;
}
function announcementCard(a){return `<article class="announcement ${a.priority==='urgent'?'urgent':''}"><div class="announcement-icon">${icon(a.pinned?'pin':'bell')}</div><div class="announcement-body"><div class="announcement-meta"><span>${a.pinned?'PINNED ANNOUNCEMENT':a.priority==='urgent'?'URGENT ANNOUNCEMENT':a.priority==='important'?'IMPORTANT':'ANNOUNCEMENT'}</span><span>${relative(a.updated_at)}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.message)}</p><div class="announcement-by">${esc(a.author)}${a.subgroup?' · '+esc(a.subgroup):' · All groups'}${a.expires_at?' · Expires '+stamp(a.expires_at):''}</div></div>${editor()?`<button class="icon-button" data-action="edit-announcement" data-id="${a.id}" aria-label="Edit ${esc(a.title)}">${icon('edit')}</button>`:''}</article>`;}
function eventCard(e,showDate=false){
  const changed=state.data.notifications.some(n=>n.event_id===e.id&&n.kind==='change'&&(!lastVisit||n.created_at>lastVisit));
  return `<article class="event-card ${e.status==='cancelled'?'cancelled':''} ${e.type==='practical'?'practical':''} ${e.type==='exam'?'exam-event':''}"><div class="event-time">${showDate?`<span class="event-day">${dateFormat(e.date,{day:'numeric',month:'short'})}</span>`:''}<strong>${esc(e.start||'TBC')}</strong><span>${esc(e.end||'Time to be confirmed')}</span><span class="time-line"></span></div><div class="event-content"><div class="event-topline"><span class="type-tag ${e.type}">${typeNames[e.type]}</span>${e.subgroup?`<span class="subgroup-tag">${esc(e.subgroup)}</span>`:''}${e.status!=='scheduled'?`<span class="status-tag ${e.status}">${e.status==='cancelled'?icon('close'):icon('refresh')}${e.status==='cancelled'?'Cancelled':'Rescheduled'}</span>`:''}${changed?'<span class="changed-tag">Updated</span>':''}</div><button class="event-title" data-action="detail" data-id="${e.id}">${esc(e.title)}</button><span class="event-subject">${esc(e.subject)}${e.instructor?' · '+esc(e.instructor):''}</span><p class="event-location">${icon('location')}${esc([e.building,e.room].filter(Boolean).join(' · ')||e.address||(e.meeting?'Online meeting':'Location to be confirmed'))}</p>${e.notes?`<p class="event-note">${esc(e.notes)}</p>`:''}<span class="event-updated">Updated ${relative(e.updatedAt)}</span></div><div class="event-side">${badge(e)}${editor()?`<button class="quick-edit" data-action="edit-event" data-id="${e.id}">${icon('edit')}Quick edit</button>`:`<button class="event-details-link" data-action="detail" data-id="${e.id}" aria-label="Details for ${esc(e.title)}">${icon('arrow')}</button>`}</div></article>`;
}
function filtered(events){return sorted(events.filter(e=>(!state.search||[e.title,e.subject,e.room,e.building,e.instructor,e.notes].join(' ').toLowerCase().includes(state.search.toLowerCase()))&&Object.entries(state.filters).every(([k,v])=>!v||e[k]===v)));}
function filterBar(examOnly=false){const events=state.data.events;return `<div class="filters"><label class="search-input">${icon('search')}<input id="event-search" type="search" placeholder="Search ${examOnly?'exams':'your schedule'}…" aria-label="Search events" value="${esc(state.search)}"></label><div class="filter-selects">${[['subject','All subjects',[...new Set(events.map(e=>e.subject))].sort().map(v=>[v,v])],...(!examOnly?[['type','All event types',Object.entries(typeNames)]]:[]),['subgroup','All groups',[...new Set(events.map(e=>e.subgroup).filter(Boolean))].sort().map(v=>[v,v])],['attendance','All attendance',Object.entries(attendance).map(([k,v])=>[k,v.label])]].map(([key,label,options])=>`<label class="sr-only" for="filter-${key}">${label}</label><select id="filter-${key}" data-filter="${key}"><option value="">${label}</option>${options.map(([value,name])=>`<option value="${esc(value)}" ${state.filters[key]===value?'selected':''}>${esc(name)}</option>`).join('')}</select>`).join('')}</div>${state.search||Object.values(state.filters).some(Boolean)?'<button class="text-button" data-action="clear-filters">Clear filters</button>':''}</div>`;}
function bindFilters(){const input=$('#event-search');if(input)input.oninput=e=>{state.search=e.target.value;updateResults();};document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=e=>{state.filters[e.target.dataset.filter]=e.target.value;updateResults();});}
function updateResults(){const el=$('#schedule-results');if(el)el.innerHTML=state.page==='exams'?examResults():state.view==='calendar'?calendarResults():agendaResults();}
function schedulePage(){return `${pageHeading('PLAN YOUR DAY','Your schedule','Every session, one clear view. All times in '+esc(zone())+'.',editor()?`<button class="button primary" data-action="new-event">${icon('plus')}Create event</button>`:'')}<div class="schedule-toolbar"><div class="segmented"><button data-action="agenda" class="${state.view==='agenda'?'active':''}">${icon('book')}Agenda</button><button data-action="calendar" class="${state.view==='calendar'?'active':''}">${icon('calendar')}Calendar</button></div><span class="muted">${state.data.events.length} events · Cancelled sessions stay visible</span></div>${filterBar()}<div id="schedule-results">${state.view==='calendar'?calendarResults():agendaResults()}</div>`;}
function agendaResults(){const events=filtered(state.data.events);if(!events.length)return empty('No matching events','Try clearing your filters, or check back for new sessions.');const dates=[...new Set(events.map(e=>e.date))];return dates.map(date=>`<section class="agenda-day"><div class="agenda-heading"><h2>${date?date===today()?'Today':dateFormat(date,{weekday:'long',day:'numeric',month:'long'}):'Date to be confirmed'}</h2><span>${events.filter(e=>e.date===date).length} events${date&&date<today()?' · Past':''}</span></div><div class="event-list">${events.filter(e=>e.date===date).map(e=>eventCard(e)).join('')}</div></section>`).join('');}
function calendarResults(){
  const month=state.month||today().slice(0,7),start=new Date(month+'-01T12:00:00Z'),offset=(start.getUTCDay()+6)%7,days=new Date(start.getUTCFullYear(),start.getUTCMonth()+1,0).getDate(),events=filtered(state.data.events);
  const title=dateFormat(month+'-01',{month:'long',year:'numeric'});
  let cells='';for(let i=0;i<Math.ceil((days+offset)/7)*7;i++){const day=i-offset+1;if(day<1||day>days){cells+='<div class="calendar-cell outside" aria-hidden="true"></div>';continue;}const date=month+'-'+String(day).padStart(2,'0');const list=events.filter(e=>e.date===date);cells+=`<div class="calendar-cell ${date===today()?'is-today':''}"><span class="calendar-day">${day}</span>${list.map(e=>`<button class="calendar-event ${e.type} ${e.status==='cancelled'?'cancelled':''}" data-action="detail" data-id="${e.id}"><strong>${esc(e.start||'TBC')}</strong><span>${esc(e.title)}</span>${e.status!=='scheduled'?`<small>${esc(e.status)}</small>`:''}</button>`).join('')}</div>`;}
  return `<section class="calendar-panel"><div class="calendar-heading"><h2>${title}</h2><div><button class="button secondary small-button" data-action="month-prev" aria-label="Previous month">←</button><button class="button secondary small-button" data-action="month-today">Today</button><button class="button secondary small-button" data-action="month-next" aria-label="Next month">→</button></div></div><p class="calendar-mobile-note">Swipe horizontally to explore the calendar, or switch to Agenda.</p><div class="calendar-scroll" tabindex="0" aria-label="Monthly calendar"><div class="calendar-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${cells}</div></div></section>${events.some(e=>!e.date)?`<section class="agenda-day"><h2>Date to be confirmed</h2>${events.filter(e=>!e.date).map(e=>eventCard(e)).join('')}</section>`:''}`;
}
function examsPage(){return `${pageHeading('A LITTLE PREPARATION','Upcoming exams','The dates, details, and instructions to help you feel ready.',editor()?`<button class="button primary" data-action="new-exam">${icon('plus')}Add exam</button>`:'')}<div class="info-banner">${icon('exam')}Bring your student ID. Always check each exam’s specific instructions before you go.</div>${filterBar(true)}<div id="schedule-results">${examResults()}</div>`;}
function examResults(){const events=filtered(state.data.events.filter(e=>e.type==='exam'));const future=events.filter(e=>!e.date||e.date>=today()),past=events.filter(e=>e.date&&e.date<today());const card=e=>`<article class="exam-card ${e.status==='cancelled'?'cancelled':''}"><div class="exam-card-date"><span>${e.date?dateFormat(e.date,{month:'short'}):'DATE'}</span><strong>${e.date?dateFormat(e.date,{day:'numeric'}):'?'}</strong><span>${e.date?dateFormat(e.date,{weekday:'short'}):'TBC'}</span></div><div class="exam-card-body"><div class="event-topline"><span class="type-tag exam">${esc(e.subject)}</span>${e.status!=='scheduled'?`<span class="status-tag ${e.status}">${esc(e.status)}</span>`:''}${e.subgroup?`<span class="subgroup-tag">${esc(e.subgroup)}</span>`:''}</div><button class="event-title" data-action="detail" data-id="${e.id}">${esc(e.title)}</button><div class="exam-facts"><span>${icon('clock')}${e.start?`${esc(e.start)}${e.end?' – '+esc(e.end):''}`:'Time to be confirmed'}${e.start&&e.end?` · ${(Number(e.end.slice(0,2))*60+Number(e.end.slice(3)))-(Number(e.start.slice(0,2))*60+Number(e.start.slice(3)))} min`:''}</span><span>${icon('location')}${esc([e.building,e.room].filter(Boolean).join(' · ')||'Location to be confirmed')}</span></div>${e.notes?`<p class="exam-instructions">${esc(e.notes)}</p>`:''}<span class="event-updated">Updated ${relative(e.updatedAt)}</span></div><div class="event-side">${badge(e)}<button class="text-button" data-action="${editor()?'edit-event':'detail'}" data-id="${e.id}">${editor()?'Edit exam':'View details'} ${icon('arrow')}</button></div></article>`;return `${future.length?future.map(card).join(''):empty('No upcoming exams','When an exam is published, you’ll find its details here.','exam')}${past.length?`<details class="past-exams"><summary>Past exams (${past.length})</summary>${past.map(card).join('')}</details>`:''}`;}
function updatesPage(){const notifications=state.data.notifications,unread=notifications.filter(n=>!n.is_read).length;return `${pageHeading('STAY IN THE KNOW','Your updates',`${unread?unread+' unread update'+(unread===1?'':'s'):'You’re all caught up'}. Schedule changes and class announcements, together.`,`<button class="button secondary" data-action="read-all">${icon('check')}Mark all as read</button>${editor()?'<button class="button primary" data-action="new-announcement">'+icon('plus')+'Post announcement</button>':''}`)}<div class="updates-layout"><section class="updates-feed">${notifications.length?notifications.map(n=>`<article class="update-card ${!n.is_read?'unread':''}"><span class="update-icon">${icon(n.kind==='announcement'?'bell':'refresh')}</span><div class="update-body"><div class="update-meta"><span>${n.kind==='announcement'?'CLASS ANNOUNCEMENT':'SCHEDULE UPDATE'}${!n.is_read?' · UNREAD':''}</span><time datetime="${esc(n.created_at)}">${relative(n.created_at)}</time></div><h3>${esc(n.title)}</h3><p>${esc(n.message)}</p><div class="update-bottom"><span>${esc(n.author)} · ${n.subgroup?esc(n.subgroup):'All groups'}</span><div>${n.event_id&&eventById(n.event_id)?`<button class="text-button" data-action="detail" data-id="${n.event_id}">View event ${icon('arrow')}</button>`:''}${!n.is_read?`<button class="text-button" data-action="read" data-id="${n.id}">Mark as read</button>`:''}</div></div></div></article>`).join(''):empty('All quiet here','New announcements and schedule changes will appear here.','bell')}</section><aside class="updates-aside"><div class="small-note">${icon('bell')}<div><strong>Updates, without the noise.</strong><p>Your read status is personal to your account and saved across visits.</p><p>Browser push is not configured. Live updates appear here while the app is open; no notification permissions are needed.</p></div></div></aside></div>`;}
function adminPage(){if(!admin()){state.page='home';return homePage();}return `${pageHeading('YOUR CLASS, YOUR WAY','Manage your class','Members, permissions, and invitations — all in one place.')}<div class="admin-grid"><section class="panel"><h2>Class details</h2><form id="settings-form"><label>Class name<input name="name" value="${esc(state.data.class.name)}" required maxlength="100"></label><label>Class timezone<input name="timezone" value="${esc(zone())}" required placeholder="Europe/Paris"><span class="field-hint">All event dates and times are interpreted in this timezone.</span></label><button class="button primary">Save settings</button><p class="form-error" role="alert"></p></form></section><section class="panel"><h2>Invite students</h2><p class="muted">Invitations only grant student access. You can revoke a code at any time.</p><form id="invite-form"><label>Subgroup (optional)<input name="subgroup" placeholder="All groups"></label><label>Expires in<select name="days"><option value="7">7 days</option><option value="30">30 days</option><option value="90">90 days</option></select></label><button class="button primary">${icon('link')}Create invitation</button><p class="form-error" role="alert"></p></form><div id="invitation-result"></div></section><section class="panel wide"><div class="section-heading"><h2>Class members</h2><button class="text-button" data-action="new-class">${icon('plus')}Create another class</button></div><p class="muted">Only administrators can assign editor or admin permissions.</p><div id="members-list" aria-live="polite">Loading members…</div></section><section class="panel wide"><h2>Active & previous invitations</h2><div id="invitations-list">Loading invitations…</div></section></div>`;}
async function loadAdmin(){
  $('#settings-form').onsubmit=async e=>{e.preventDefault();try{await send(`${base()}/settings`,Object.fromEntries(new FormData(e.target)),'PATCH');toast('Class settings saved.');await boot();}catch(error){e.target.querySelector('.form-error').textContent=error.message;}};
  $('#invite-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{const result=await send(`${base()}/invitations`,Object.fromEntries(new FormData(e.target)));const link=location.origin+'/#join='+encodeURIComponent(result.code);$('#invitation-result').innerHTML=`<div class="invitation-result"><strong>Invitation ready. Copy it now.</strong><p>The code is only shown once.</p><label>Student invitation link<input readonly value="${esc(link)}"></label><label>Invitation code<input readonly value="${esc(result.code)}"></label><button class="button secondary" data-action="copy-invite" data-value="${esc(link)}">Copy link</button></div>`;await loadInvitations();}catch(error){e.target.querySelector('.form-error').textContent=error.message;}finally{btn.disabled=false;}};
  try{const members=await api(`${base()}/members`);if(!$('#members-list'))return;$('#members-list').innerHTML=members.map(m=>`<div class="member-row"><span class="avatar">${esc(m.name[0])}</span><div class="member-name"><strong>${esc(m.name)}</strong><span>${esc(m.email)}</span></div><label class="sr-only" for="role-${m.id}">Role for ${esc(m.name)}</label><select id="role-${m.id}" data-member-role="${m.id}">${['student','editor','admin'].map(r=>`<option ${r===m.role?'selected':''}>${r}</option>`).join('')}</select><label class="sr-only" for="group-${m.id}">Subgroup for ${esc(m.name)}</label><input id="group-${m.id}" data-member-group="${m.id}" value="${esc(m.subgroup)}" placeholder="All groups"><button class="button secondary small-button" data-action="save-member" data-id="${m.id}">Save</button><button class="icon-button danger" data-action="remove-member" data-id="${m.id}" data-name="${esc(m.name)}" aria-label="Remove ${esc(m.name)}">${icon('close')}</button></div>`).join('');await loadInvitations();}catch(error){if($('#members-list'))$('#members-list').textContent=error.message;}
}
async function loadInvitations(){const invitations=await api(`${base()}/invitations`);if(!$('#invitations-list'))return;$('#invitations-list').innerHTML=invitations.length?invitations.map(i=>`<div class="invitation-row"><div><strong>${esc(i.subgroup||'All groups')}</strong><span>Expires ${stamp(i.expires_at)}</span></div><span class="status-tag ${i.revoked?'cancelled':''}">${i.revoked?'Revoked':i.expires_at<new Date().toISOString()?'Expired':'Active'}</span>${!i.revoked?`<button class="text-button danger" data-action="revoke" data-id="${i.id}">Revoke</button>`:''}</div>`).join(''):'<p class="muted">No invitations yet. Create one above.</p>';}

function openModal(title,content,cls=''){const modal=$('#modal');modal.className=cls;modal.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${content}</div>`;if(!modal.open)modal.showModal();}
function detail(eventId){const e=eventById(eventId);if(!e){toast('This event is no longer available to your group.');return;}openModal(esc(e.title),`<div class="event-topline"><span class="type-tag ${e.type}">${typeNames[e.type]}</span>${badge(e)}${e.status!=='scheduled'?`<span class="status-tag ${e.status}">${esc(e.status)}</span>`:''}</div><p class="muted">${esc(e.subject)}${e.subgroup?' · '+esc(e.subgroup):' · All groups'}${e.seriesId?' · Recurring event':''}</p><dl class="detail-grid">${[['calendar','Date',dateFormat(e.date,{weekday:'long',day:'numeric',month:'long',year:'numeric'})],['clock','Time',`${e.start||'Start to be confirmed'}${e.end?' – '+e.end:' · End to be confirmed'}`],['location','Location',[e.building,e.room,e.address].filter(Boolean).join(' · ')||'To be confirmed'],['people','Instructor',e.instructor||'To be confirmed']].map(([ic,label,value])=>`<div><dt>${icon(ic)}${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>${e.meeting?`<a class="button secondary" href="${esc(e.meeting)}" target="_blank" rel="noopener noreferrer">${icon('link')}Open online meeting</a>`:''}<h3>Instructions</h3><p class="pre-wrap">${esc(e.notes||'No additional instructions.')}</p>${e.links?`<h3>Resources</h3><div class="resource-links">${e.links.split('\n').filter(Boolean).map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon('link')}Resource ${i+1} · ${esc(new URL(url).hostname)}</a>`).join('')}</div>`:''}<p class="field-hint">Last updated ${stamp(e.updatedAt)} · All times in ${esc(zone())}</p>${editor()?`<div class="modal-actions"><button class="button secondary" data-action="history" data-id="${e.id}">Version history</button><button class="button primary" data-action="edit-event" data-id="${e.id}">${icon('edit')}Edit event</button></div>`:''}`);}
let eventDraft=null, originalEvent=null, seriesVersions=null, announcementDraft=null, announcementOriginal=null;
function editEvent(eventId,exam=false){
  originalEvent=eventId?structuredClone(eventById(eventId)):null;
  if(eventId&&!originalEvent){toast('Event unavailable.');return;}
  eventDraft=originalEvent?{...originalEvent,scope:'occurrence'}:{title:'',subject:'',type:exam?'exam':'lecture',date:today(),start:'',end:'',building:'',room:'',address:'',meeting:'',instructor:'',attendance:'unknown',status:'scheduled',subgroup:'',notes:'',links:'',repeatCount:1};
  seriesVersions=Object.fromEntries(state.data.events.filter(e=>e.seriesId===originalEvent?.seriesId).map(e=>[e.id,e.version]));eventForm();
}
function inputField(key,label,type='text',hint=''){return `<label>${label}<input name="${key}" type="${type}" aria-label="${label}" value="${esc(eventDraft[key]||'')}" ${['title','subject'].includes(key)?'required maxlength="250"':''}>${hint?`<span class="field-hint">${hint}</span>`:''}</label>`;}
function eventForm(){
  const d=eventDraft;openModal(originalEvent?'Edit event':'Create event',`<p class="muted">${originalEvent?'Make a quick change, then review it before publishing.':'Add the confirmed information. Leave unknown dates, times, and locations blank.'}</p><form id="event-form"><div class="form-grid">${inputField('title','Event title')}${inputField('subject','Subject')}<label>Event type<select name="type" aria-label="Event type">${Object.entries(typeNames).map(([key,label])=>`<option value="${key}" ${d.type===key?'selected':''}>${label}</option>`).join('')}</select></label>${inputField('subgroup','Class subgroup (optional)','text','Leave blank to share with every group.')}${inputField('date','Date','date','Leave blank: To be confirmed.')}${inputField('instructor','Instructor (optional)')}${inputField('start','Start time','time','Leave blank: To be confirmed.')}${inputField('end','End time','time','Leave blank: To be confirmed.')}${inputField('building','Building (optional)')}${inputField('room','Room (optional)')}<label>Attendance<select name="attendance" aria-label="Attendance">${Object.entries(attendance).map(([key,a])=>`<option value="${key}" ${d.attendance===key?'selected':''}>${a.label}</option>`).join('')}</select><span class="field-hint">Unknown until explicitly confirmed.</span></label><label>Event status<select name="status" aria-label="Event status">${['scheduled','rescheduled','cancelled'].map(key=>`<option value="${key}" ${d.status===key?'selected':''}>${key[0].toUpperCase()+key.slice(1)}</option>`).join('')}</select></label>${inputField('address','Address (optional)')}${inputField('meeting','Online meeting link (optional)','url')}<label class="full-width">Instructions<textarea name="notes" rows="3" maxlength="4000">${esc(d.notes)}</textarea></label><label class="full-width">Resource links<textarea name="links" rows="2" placeholder="One https:// link per line">${esc(d.links)}</textarea></label>${originalEvent?.seriesId?`<label class="full-width">Apply changes to<select name="scope"><option value="occurrence" ${d.scope==='occurrence'?'selected':''}>Only this occurrence</option><option value="series" ${d.scope==='series'?'selected':''}>The entire series (including past occurrences)</option></select><span class="field-hint">A date change shifts each occurrence by the same number of days.</span></label>`:!originalEvent?`<label class="full-width">Weekly recurrence<select name="repeatCount">${[1,2,4,8,12,16,24,52].map(n=>`<option value="${n}" ${Number(d.repeatCount)===n?'selected':''}>${n===1?'Does not repeat':n+' weekly occurrences'}</option>`).join('')}</select></label>`:''}</div><p class="field-hint">All dates and times use ${esc(zone())}.</p><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="button secondary" data-action="close-modal">Cancel</button><button class="button primary">Preview ${icon('arrow')}</button></div></form>`,'large-modal');
  $('#event-form').onsubmit=e=>{e.preventDefault();eventDraft={...eventDraft,...Object.fromEntries(new FormData(e.target))};eventPreview();};
}
const fieldLabels={title:'Title',subject:'Subject',type:'Event type',subgroup:'Subgroup',date:'Date',start:'Start time',end:'End time',building:'Building',room:'Room',address:'Address',meeting:'Meeting link',instructor:'Instructor',attendance:'Attendance',status:'Status',notes:'Instructions',links:'Resource links'};
const displayValue=(key,value)=>key==='attendance'?attendance[value]?.label||'Unknown':key==='type'?typeNames[value]:key==='date'?dateFormat(value):value||'To be confirmed';
function eventPreview(){const d=eventDraft;const changes=Object.keys(fieldLabels).filter(key=>!originalEvent||d[key]!==originalEvent[key]);openModal('Review before publishing',`<p class="muted">${originalEvent?'Connected students will see these changes as soon as you publish.':'This event will be added to your class schedule.'}</p>${d.scope==='series'?'<div class="info-banner">These changes apply to the entire series.</div>':''}${!originalEvent&&Number(d.repeatCount)>1?`<div class="info-banner">${d.repeatCount} weekly occurrences will be created.</div>`:''}<h3>${esc(d.title)}</h3><div class="preview-changes">${changes.map(key=>`<div><strong>${fieldLabels[key]}</strong>${originalEvent?`<span class="old-value">${esc(displayValue(key,originalEvent[key]))}</span>${icon('arrow')}`:''}<span>${esc(displayValue(key,d[key]))}</span></div>`).join('')||'<p>No changes to publish.</p>'}</div><p class="form-error" role="alert" id="publish-error"></p><div class="modal-actions"><button class="button secondary" data-action="event-back">Back to edit</button><button class="button primary" data-action="publish-event" ${originalEvent&&!changes.length?'disabled':''}>${icon('check')}Publish ${originalEvent?'changes':'event'}</button></div>`,'large-modal');}
async function publishEvent(button){button.disabled=true;try{const payload={...eventDraft,version:originalEvent?.version,seriesVersions};await send(originalEvent?`${base()}/events/${originalEvent.id}`:`${base()}/events`,payload,originalEvent?'PATCH':'POST');$('#modal').close();toast(originalEvent?'Changes published. Your class is up to date.':'Event created and shared with your class.');await loadClass();}catch(error){$('#publish-error').textContent=error.message;if(error.status===409){const p=document.createElement('p');p.innerHTML='<button class="text-button" data-action="reload-event">Load the latest version (replaces your draft)</button>';$('#publish-error').after(p);}button.disabled=false;}}

function editAnnouncement(announcementId){announcementOriginal=announcementId?state.data.announcements.find(a=>a.id===announcementId):null;announcementDraft=announcementOriginal?{...announcementOriginal}:{title:'',message:'',subgroup:'',priority:'normal',pinned:false,expires_at:''};announcementForm();}
function announcementForm(){const d=announcementDraft;openModal(announcementOriginal?'Edit announcement':'Post announcement',`<form id="announcement-form"><label>Title<input name="title" required maxlength="200" value="${esc(d.title)}"></label><label>Message<textarea name="message" required rows="5" maxlength="5000">${esc(d.message)}</textarea></label><div class="form-grid"><label>Priority<select name="priority" aria-label="Priority">${['normal','important','urgent'].map(p=>`<option value="${p}" ${p===d.priority?'selected':''}>${p[0].toUpperCase()+p.slice(1)}</option>`).join('')}</select></label><label>Subgroup (optional)<input name="subgroup" value="${esc(d.subgroup)}" placeholder="All groups"></label><label class="full-width">Expiration (optional)<input type="datetime-local" name="expires_at" value="${d.expires_at?new Date(new Date(d.expires_at).getTime()-new Date(d.expires_at).getTimezoneOffset()*60000).toISOString().slice(0,16):''}"><span class="field-hint">Expiration uses your device timezone. Leave blank to keep it visible.</span></label>${admin()?`<label class="checkbox-label full-width"><input type="checkbox" name="pinned" ${d.pinned?'checked':''}>Pin this announcement</label>`:''}</div><p class="form-error" role="alert"></p><div class="modal-actions"><button class="button secondary" type="button" data-action="close-modal">Cancel</button><button class="button primary">Preview ${icon('arrow')}</button></div></form>`);$('#announcement-form').onsubmit=e=>{e.preventDefault();const raw=Object.fromEntries(new FormData(e.target));announcementDraft={...d,...raw,pinned:admin()?Boolean(raw.pinned):Boolean(d.pinned),expires_at:raw.expires_at?new Date(raw.expires_at).toISOString():''};openModal('Review announcement',`<span class="type-tag">${esc(announcementDraft.priority)}${announcementDraft.pinned?' · Pinned':''}</span><h3>${esc(announcementDraft.title)}</h3><p class="pre-wrap">${esc(announcementDraft.message)}</p><p class="muted">To: ${esc(announcementDraft.subgroup||'All groups')}${announcementDraft.expires_at?' · Expires '+stamp(announcementDraft.expires_at):''}</p><p class="form-error" id="announcement-error" role="alert"></p><div class="modal-actions"><button class="button secondary" data-action="announcement-back">Back to edit</button><button class="button primary" data-action="publish-announcement">Publish announcement</button></div>`);};}
async function showHistory(eventId){try{const history=await api(`${base()}/events/${eventId}/history`);openModal('Event version history',`<p class="muted">Every published change, with its author and time. Restoring creates a new version.</p>${history.map(h=>`<article class="history-item"><div class="section-heading"><strong>Version ${h.version}</strong><span>${stamp(h.created_at)}</span></div><p>${esc(h.author)}</p>${h.changed_fields.length?`<ul>${h.changed_fields.map(c=>`<li>${esc(c.message)}</li>`).join('')}</ul>`:'<p>Event created.</p>'}${admin()&&h.version!==eventById(eventId).version?`<button class="button secondary small-button" data-action="restore-preview" data-id="${eventId}" data-version="${h.version}">Review restoration</button>`:''}</article>`).join('')}`); }catch(error){toast(error.message);}}
let restoreDraft=null;
async function restorePreview(eventId,version){const history=await api(`${base()}/events/${eventId}/history`);const h=history.find(v=>v.version===Number(version)),current=eventById(eventId);restoreDraft={eventId,restoreVersion:Number(version),version:current.version};openModal('Review restoration',`<p>Restore version ${esc(version)} of <strong>${esc(current.title)}</strong>?</p><div class="preview-changes">${Object.keys(fieldLabels).filter(k=>current[k]!==h.data[k]).map(k=>`<div><strong>${fieldLabels[k]}</strong><span class="old-value">${esc(displayValue(k,current[k]))}</span>${icon('arrow')}<span>${esc(displayValue(k,h.data[k]))}</span></div>`).join('')}</div><p class="muted">This affects only this occurrence. The restoration will be recorded as a new version and shared with students.</p><p class="form-error" id="restore-error" role="alert"></p><div class="modal-actions"><button class="button secondary" data-action="close-modal">Cancel</button><button class="button primary" data-action="restore-confirm">Restore & publish</button></div>`,'large-modal');}

document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action],[data-page]');if(!el)return;
  if(el.dataset.page){state.page=el.dataset.page;if(state.page==='exams')state.filters.type='';render();window.scrollTo({top:0});$('#main')?.focus({preventScroll:true});return;}
  const action=el.dataset.action,eventId=el.dataset.id;
  try {
    if(action==='home'){event.preventDefault();state.page='home';render();}
    if(action==='auth-switch'){authMode=authMode==='login'?'register':'login';renderAuth();}
    if(action==='demo-login'){el.disabled=true;try{const result=await send('/auth/login',{email:`${el.dataset.role}@medclass.demo`,password:'MedClassDemo2026!'});csrf=result.csrf;await boot();}catch(error){renderAuth(error.message+' Demo accounts are available after running npm run seed.');}}
    if(action==='logout'){await send('/auth/logout');state.stream?.close();state.user=null;state.data=null;renderAuth();}
    if(action==='account'){
      openModal('Your account',`<p><strong>${esc(state.user.name)}</strong><br>${esc(state.user.email)}</p><label>Your class<select id="mobile-class-select">${state.classes.map(c=>`<option value="${esc(c.id)}" ${c.id===state.classId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><p class="muted">${esc(state.data.subgroup||'All groups')} · ${esc(state.data.role)}</p><div class="modal-actions"><button class="button secondary" data-action="join">Join another class</button><button class="button secondary" data-action="account-logout">Sign out</button></div>`);
      $('#mobile-class-select').onchange=async e=>{state.classId=e.target.value;localStorage.setItem('medclass-class',state.classId);state.page='home';state.filters={subject:'',type:'',subgroup:'',attendance:''};state.search='';$('#modal').close();try{await loadClass(true);connect();}catch(error){handleLoadError(error);}};
    }
    if(action==='account-logout'){$('#modal').close();await send('/auth/logout');state.stream?.close();state.user=null;state.data=null;renderAuth();}
    if(action==='reload')await boot();
    if(action==='close-modal')$('#modal').close();
    if(action==='new-event')editEvent();
    if(action==='new-exam')editEvent(null,true);
    if(action==='edit-event')editEvent(eventId);
    if(action==='detail')detail(eventId);
    if(action==='event-back')eventForm();
    if(action==='publish-event')await publishEvent(el);
    if(action==='reload-event'){await loadClass();editEvent(originalEvent.id);}
    if(action==='new-announcement')editAnnouncement();
    if(action==='edit-announcement')editAnnouncement(eventId);
    if(action==='announcement-back')announcementForm();
    if(action==='publish-announcement'){el.disabled=true;try{await send(announcementOriginal?`${base()}/announcements/${announcementOriginal.id}`:`${base()}/announcements`,announcementDraft,announcementOriginal?'PATCH':'POST');$('#modal').close();toast('Announcement published.');await loadClass();}catch(error){$('#announcement-error').textContent=error.message;el.disabled=false;}}
    if(action==='agenda'||action==='calendar'){state.view=action;render();}
    if(action==='month-prev'||action==='month-next'){const d=new Date(state.month+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+(action==='month-next'?1:-1));state.month=d.toISOString().slice(0,7);updateResults();}
    if(action==='month-today'){state.month=today().slice(0,7);updateResults();}
    if(action==='clear-filters'){state.search='';state.filters={subject:'',type:'',subgroup:'',attendance:''};render();}
    if(action==='read'){await send(`${base()}/notifications/${eventId}/read`);await loadClass();}
    if(action==='read-all'){await send(`${base()}/notifications/read-all`);await loadClass();toast('All updates marked as read.');}
    if(action==='history')await showHistory(eventId);
    if(action==='restore-preview')await restorePreview(eventId,el.dataset.version);
    if(action==='restore-confirm'){el.disabled=true;try{await send(`${base()}/events/${restoreDraft.eventId}/restore`,restoreDraft);$('#modal').close();toast('Earlier version restored and published.');await loadClass();}catch(error){$('#restore-error').textContent=error.message;el.disabled=false;}}
    if(action==='copy-invite'){try{await navigator.clipboard.writeText(el.dataset.value);toast('Invitation link copied.');}catch{toast('Copy the invitation from the field above.');}}
    if(action==='revoke'){await send(`${base()}/invitations/${eventId}`,{},'DELETE');toast('Invitation revoked.');await loadInvitations();}
    if(action==='save-member'){await send(`${base()}/members/${eventId}`,{role:document.querySelector(`[data-member-role="${eventId}"]`).value,subgroup:document.querySelector(`[data-member-group="${eventId}"]`).value},'PATCH');toast('Member permissions saved.');await boot();}
    if(action==='remove-member'){openModal('Remove class member',`<p>Remove <strong>${esc(el.dataset.name)}</strong> from this class? They will immediately lose access.</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">Cancel</button><button class="button danger-button" data-action="remove-member-confirm" data-id="${eventId}">Remove member</button></div>`);}
    if(action==='remove-member-confirm'){await send(`${base()}/members/${eventId}`,{},'DELETE');$('#modal').close();toast('Member removed.');await boot();}
    if(action==='join'){openModal('Join another class','<form id="join-modal-form"><label>Invitation code<input name="code" required placeholder="Paste your class invitation code"></label><p class="form-error" role="alert"></p><button class="button primary">Join as a student</button></form>');$('#join-modal-form').onsubmit=async e=>{e.preventDefault();try{const result=await send('/join',Object.fromEntries(new FormData(e.target)));state.classId=result.classId;$('#modal').close();await boot();toast('You’ve joined the class as a student.');}catch(error){e.target.querySelector('.form-error').textContent=error.message;}};}
    if(action==='new-class'){openModal('Create a class','<form id="new-class-form"><label>Class name<input name="name" required placeholder="Medicine · Class of 2029"></label><label>Timezone<input name="timezone" required value="Europe/Paris"></label><p class="form-error" role="alert"></p><button class="button primary">Create class</button></form>');$('#new-class-form').onsubmit=async e=>{e.preventDefault();try{const result=await send('/classes',Object.fromEntries(new FormData(e.target)));state.classId=result.id;$('#modal').close();await boot();}catch(error){e.target.querySelector('.form-error').textContent=error.message;}};}
  } catch(error){toast(error.message);}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('#modal').close();}});
if(invitationCode)authMode='register';
boot();
